(() => {
  'use strict';

  const THEMES = ['system','light','dark'];
  const ORDER_STATUSES = ['Received','Bear notified','Preparing','Out for Bear Delivery','Delivered','Cancelled'];
  const state = { user:null, products:[], favourites:[], cart:[], loyalty:null, orders:[], fun:null, admin:null, dateIdeas:[], roomServiceMenu:[], tiers:[] };
  const ui = { shopQuery:'', shopCategory:'All', funTab:'dates', adminTab:'dashboard', loyaltyTarget:null, roulette:null, brandClicks:0, greenClicks:0, zeroClicks:0, deferredInstall:null, toastTimer:null, busy:false };

  const $ = (s,r=document) => r.querySelector(s);
  const $$ = (s,r=document) => [...r.querySelectorAll(s)];
  const view = $('#view');

  init();

  async function init() {
    bindShell();
    setTheme(localStorage.getItem('duckBear.theme') || 'system', false);
    registerPwa();
    await boot();
  }

  async function boot() {
    setBusy(true, 'Connecting to Duck & Bear HQ…');
    try {
      const setup = await api('/api/setup/status', { authOptional:true });
      if (setup.setupRequired) {
        setBusy(false);
        renderSetup(setup.setupSecretConfigured);
        return;
      }
      await reloadAll();
    } catch (err) {
      setBusy(false);
      if (err.status === 401) renderLogin();
      else renderFatal(err.message || 'Could not connect to Duck & Bear HQ.');
    }
  }

  async function reloadAll() {
    const data = await api('/api/bootstrap');
    Object.assign(state, data);
    if (state.user?.role === 'admin' && state.admin?.memberBalances?.length) {
      if (!ui.loyaltyTarget || !state.admin.memberBalances.some(x=>x.userId===ui.loyaltyTarget)) ui.loyaltyTarget = state.admin.memberBalances[0].userId;
      const l = await api(`/api/loyalty?userId=${encodeURIComponent(ui.loyaltyTarget)}`);
      state.loyalty = l.loyalty;
    } else if (state.user) ui.loyaltyTarget = state.user.id;
    setBusy(false);
    updateShell();
    render();
  }

  async function api(url, options={}) {
    const init = { method: options.method || 'GET', headers: { ...(options.headers || {}) }, credentials:'same-origin' };
    if (options.body !== undefined) {
      if (options.body instanceof FormData) init.body = options.body;
      else { init.headers['Content-Type']='application/json'; init.body=JSON.stringify(options.body); }
    }
    let response;
    try { response = await fetch(url, init); }
    catch { const e=new Error('You appear to be offline. The app shell still works, but shared data needs a connection.'); e.status=0; throw e; }
    const type=response.headers.get('content-type')||'';
    const data=type.includes('application/json') ? await response.json().catch(()=>({})) : null;
    if (!response.ok) {
      const e=new Error(data?.error || `Request failed (${response.status}).`); e.status=response.status;
      if (response.status===401 && !options.authOptional) { state.user=null; updateShell(); renderLogin(); }
      throw e;
    }
    return data;
  }

  function setBusy(on, message='Working…') {
    ui.busy=on;
    if (on) view.innerHTML=`<section class="page"><div class="loading-card"><div class="loading-orbit">🦆 <span>↔</span> 🐻</div><strong>${escapeHTML(message)}</strong><p class="muted">The relationship database is doing very serious things.</p></div></section>`;
  }

  function renderSetup(secretConfigured) {
    updateShell(false);
    view.innerHTML=`<section class="page auth-page">
      <div class="auth-shell">
        <div class="auth-art"><div class="auth-emoji">🦆💚🐻</div><span class="badge">FIRST BOOT</span><h1>Set up Duck & Bear HQ</h1><p>This creates the private admin and member accounts. Passwords are hashed server-side and the setup key is never stored in the website code.</p></div>
        <form class="auth-card" id="setupForm">
          <p class="eyebrow">One-time setup</p><h2>Create the two accounts</h2>
          ${secretConfigured ? '' : '<div class="warning-box">The Worker secret <code>SETUP_SECRET</code> has not been added yet. The form is ready, but Cloudflare must have that secret before setup can complete.</div>'}
          <label>Cloudflare setup key<input id="setupSecret" type="password" minlength="8" autocomplete="off" required ${secretConfigured?'':'disabled'} /></label>
          <div class="auth-split">
            <fieldset><legend>Bear Admin</legend><label>Name<input id="adminDisplay" value="Zach" maxlength="50" required /></label><label>Username<input id="adminUser" value="zach" maxlength="30" autocomplete="username" required /></label><label>Password<input id="adminPass" type="password" minlength="8" maxlength="128" autocomplete="new-password" required /></label></fieldset>
            <fieldset><legend>Yaya Member</legend><label>Name<input id="memberDisplay" value="Guannan" maxlength="50" required /></label><label>Username<input id="memberUser" value="guannan" maxlength="30" autocomplete="username" required /></label><label>Password<input id="memberPass" type="password" minlength="8" maxlength="128" autocomplete="new-password" required /></label></fieldset>
          </div>
          <button class="primary full" type="submit" ${secretConfigured?'':'disabled'}>Create Duck & Bear HQ</button>
        </form>
      </div>
    </section>`;
    $('#setupForm')?.addEventListener('submit', submitSetup);
  }

  async function submitSetup(e) {
    e.preventDefault();
    const btn=e.submitter; setButtonBusy(btn,true,'Creating HQ…');
    try {
      await api('/api/setup',{method:'POST',authOptional:true,body:{
        setupSecret:$('#setupSecret').value,
        admin:{displayName:$('#adminDisplay').value,username:$('#adminUser').value,password:$('#adminPass').value},
        member:{displayName:$('#memberDisplay').value,username:$('#memberUser').value,password:$('#memberPass').value}
      }});
      toast('Accounts created. Sign in to open HQ.'); renderLogin();
    } catch(err) { toast(err.message,true); }
    finally { setButtonBusy(btn,false); }
  }

  function renderLogin() {
    state.user=null; updateShell(false);
    view.innerHTML=`<section class="page auth-page">
      <div class="auth-shell login-shell">
        <div class="auth-art"><div class="auth-emoji">🦆🛍️🐻</div><span class="badge">MEMBERS ONLY</span><h1>Duck & Bear HQ</h1><p>The £0 Shop, Yaya Points, room service, complaints, memories and an unreasonable amount of administration.</p><div class="login-perks"><span>£0.00 forever</span><span>Shared history</span><span>Installable app</span></div></div>
        <form class="auth-card" id="loginForm"><p class="eyebrow">Secure-ish entrance</p><h2>Sign in</h2><label>Username<input id="loginUser" maxlength="30" autocomplete="username" required /></label><label>Password<input id="loginPass" type="password" maxlength="128" autocomplete="current-password" required /></label><button class="primary full" type="submit">Enter HQ</button><p class="muted tiny">The shop is free. The login is not optional.</p></form>
      </div>
    </section>`;
    $('#loginForm')?.addEventListener('submit', submitLogin);
  }

  async function submitLogin(e) {
    e.preventDefault(); const btn=e.submitter; setButtonBusy(btn,true,'Checking credentials…');
    try { await api('/api/auth/login',{method:'POST',authOptional:true,body:{username:$('#loginUser').value,password:$('#loginPass').value}}); await reloadAll(); toast('Welcome to Duck & Bear HQ.'); }
    catch(err){ toast(err.message,true); setButtonBusy(btn,false); }
  }

  function renderFatal(message) {
    updateShell(false);
    view.innerHTML=`<section class="page"><div class="empty"><span class="emoji">🚨</span><strong>HQ connection problem</strong><div>${escapeHTML(message)}</div><button class="primary" type="button" data-action="retry-boot">Try again</button></div></section>`;
  }

  function routeName() {
    if (!state.user) return 'login';
    const r=(location.hash||'#home').slice(1).split('?')[0].toLowerCase();
    if (r==='rewards') return 'loyalty';
    const allowed=['home','shop','loyalty','orders','fun','admin'];
    if (r==='admin' && state.user.role!=='admin') return 'home';
    return allowed.includes(r)?r:'home';
  }

  function render() {
    if (!state.user) return;
    updateNav(); updateCartBadge();
    const route=routeName();
    if(route==='home')renderHome();
    else if(route==='shop')renderShop();
    else if(route==='loyalty')renderLoyalty();
    else if(route==='orders')renderOrders();
    else if(route==='fun')renderFun();
    else if(route==='admin')renderAdmin();
    view.focus({preventScroll:true});
  }

  function updateShell(logged=Boolean(state.user)) {
    $('#cartBtn').hidden=!logged;
    $('#profileBtn').hidden=!logged;
    $('#adminNav').hidden=!(logged && state.user?.role==='admin');
    $('#storageStatus').textContent=logged?'Synced with Cloudflare':'Private shared app';
    $('.mobile-nav').style.display=logged?'':'none';
    $('.desktop-nav').style.display=logged?'':'none';
    if(logged) $('#profileBtn').textContent=state.user.role==='admin'?'🛠️':'💚';
  }
  function updateNav(){ const r=routeName(); $$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===r)); }
  function updateCartBadge(){ $('#cartCount').textContent=String(cartQty()); }
  function cartQty(){ return state.cart.reduce((s,x)=>s+Number(x.qty||0),0); }
  function loyaltyPerson(){ if(state.user?.role!=='admin')return state.user; const x=state.admin?.users?.find(u=>u.id===ui.loyaltyTarget); return x?{id:x.id,displayName:x.display_name,role:x.role}:state.user; }

  function renderHome() {
    const balance=state.loyalty?.balance||0;
    const delivered=state.orders.filter(o=>o.status==='Delivered').length;
    const recent=[...state.orders.slice(0,4).map(o=>({at:o.created_at,icon:'📦',title:o.order_number,note:`${o.status} · ${itemCount(o)} item(s)`})),...(state.loyalty?.transactions||[]).slice(0,4).map(t=>({at:t.created_at,icon:t.delta>0?'⭐':'🎟️',title:t.label,note:`${signed(t.delta)} points · balance ${t.balance_after}`}))].sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,6);
    const who=loyaltyPerson()?.displayName||'Yaya';
    view.innerHTML=`<section class="page">
      <div class="hero"><div class="hero-copy"><p class="eyebrow">Guannan Headquarters · Cloudflare edition</p><h1>Everything costs £0.00. The audit trail is still immaculate.</h1><p class="lead">A real shared shop and loyalty app with synced orders, Yaya Points, rewards, room service, memories and completely unnecessary corporate controls.</p><div class="hero-actions"><a class="primary" href="#shop">Enter the £0 Shop</a><a class="secondary" href="#loyalty">${escapeHTML(who)}: ${balance} points</a><button class="ghost" type="button" data-action="account">Account & exports</button></div></div><div class="hero-art" aria-hidden="true"><div class="duck-bear-orbit"><span class="orbit-main">🦆🐻</span><span class="orbit-badge one">FREE SHIPPING</span><span class="orbit-badge two">SHARED CLOUD</span></div></div></div>
      <div class="stats-grid">${stat('Yaya balance',balance,'points available')}${stat('Orders',state.orders.length,`${delivered} delivered`)}${stat('Cart',cartQty(),'items costing nothing')}${stat('Role',state.user.role==='admin'?'Bear Admin':'Yaya Member','authorised nonsense')}</div>
      <section class="section"><div class="section-head"><h2>What are we doing?</h2></div><div class="cards-3"><a class="card action-card" href="#shop"><div><div class="big-icon">🛍️</div><h2>Spend £0.00</h2><p>Real cart, checkout, favourites and synced order history.</p></div><span class="quick-arrow">Browse shop →</span></a><a class="card action-card" href="#loyalty"><div><div class="big-icon">⭐</div><h2>Collect points</h2><p>Earn, redeem and inspect every change in the proper ledger.</p></div><span class="quick-arrow">Open loyalty →</span></a><a class="card action-card" href="#fun"><div><div class="big-icon">🎲</div><h2>Cause trouble</h2><p>Date roulette, breakfast, memories, reviews, complaints and adventures.</p></div><span class="quick-arrow">Open fun stuff →</span></a></div></section>
      <section class="section"><div class="section-head"><h2>Recent activity</h2><a href="#orders">Order history</a></div><div class="transaction-list">${recent.length?recent.map(x=>`<div class="transaction-item"><div class="tx-icon">${x.icon}</div><div class="tx-copy"><strong>${escapeHTML(x.title)}</strong><small>${escapeHTML(x.note)} · ${fmtDate(x.at)}</small></div></div>`).join(''):empty('🧾','Nothing logged yet','Your future nonsense will appear here.')}</div></section>
    </section>`;
  }
  function stat(label,value,note){ return `<div class="stat-card"><span>${escapeHTML(label)}</span><strong>${escapeHTML(value)}</strong><small>${escapeHTML(note)}</small></div>`; }

  function renderShop() {
    const categories=['All',...new Set(state.products.map(p=>p.category))]; const q=ui.shopQuery.trim().toLowerCase(); const filtered=state.products.filter(p=>(ui.shopCategory==='All'||p.category===ui.shopCategory)&&(!q||`${p.name} ${p.category} ${p.blurb}`.toLowerCase().includes(q)));
    view.innerHTML=`<section class="page"><div class="page-head"><div><p class="eyebrow">Free-range commerce</p><h1>The £0 Shop</h1><p>A proper store experience with cart, favourites, order history and prices that refuse to increase.</p></div><button class="secondary" type="button" data-action="open-cart">View cart (${cartQty()})</button></div><div class="toolbar"><div class="search-box"><input id="shopSearch" type="search" value="${escapeAttr(ui.shopQuery)}" placeholder="Search the shop…" /></div><select id="shopCategory">${categories.map(c=>`<option ${c===ui.shopCategory?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select><button class="ghost" type="button" data-action="favourites-only">♥ ${state.favourites.length} favourites</button></div><div class="product-grid">${filtered.length?filtered.map(productCard).join(''):empty('🔎','No products found','Try a different search.')}</div></section>`;
    $('#shopSearch')?.addEventListener('input',e=>{ui.shopQuery=e.target.value;renderShop();requestAnimationFrame(()=>{const x=$('#shopSearch');x?.focus();x?.setSelectionRange(x.value.length,x.value.length);});});
    $('#shopCategory')?.addEventListener('change',e=>{ui.shopCategory=e.target.value;renderShop();});
  }
  function productCard(p){ const fav=state.favourites.includes(p.id); return `<article class="product-card"><button class="favourite-btn ${fav?'active':''}" type="button" data-action="favourite" data-id="${escapeAttr(p.id)}">${fav?'♥':'♡'}</button><button class="product-image card-click" type="button" data-action="product" data-id="${escapeAttr(p.id)}" aria-label="View ${escapeAttr(p.name)}">${p.emoji}</button><div class="product-body"><span class="eyebrow">${escapeHTML(p.category)}</span><h3>${escapeHTML(p.name)}</h3><p>${escapeHTML(p.blurb)}</p><div class="product-meta"><div><div class="price zero-total">£0.00</div><div class="stock">● ${escapeHTML(p.stock_label)}</div></div><button class="primary" type="button" data-action="add-cart" data-id="${escapeAttr(p.id)}">Add</button></div></div></article>`; }
  function openProduct(pid){ const p=state.products.find(x=>x.id===pid); if(!p)return; const fav=state.favourites.includes(pid); $('#productDialogContent').innerHTML=`<div class="product-detail"><div class="product-detail-art">${p.emoji}</div><div class="product-detail-copy"><div class="modal-head"><div><p class="eyebrow">${escapeHTML(p.category)} · ★ ${Number(p.rating).toFixed(1)}</p><h2>${escapeHTML(p.name)}</h2></div><button class="icon-btn dialog-close" type="button">✕</button></div><p class="lead">${escapeHTML(p.description||p.blurb)}</p><div class="price zero-total">£0.00</div><p class="stock">● ${escapeHTML(p.stock_label)}</p><div class="dialog-actions"><button class="primary" type="button" data-action="add-cart" data-id="${escapeAttr(p.id)}">Add to cart — £0.00</button><button class="secondary" type="button" data-action="favourite" data-id="${escapeAttr(p.id)}">${fav?'♥ Saved':'♡ Save favourite'}</button></div></div></div>`; $('#productDialog').showModal(); }

  async function addCart(pid){ try { const d=await api('/api/cart',{method:'POST',body:{productId:pid,action:'add',quantity:1}}); state.cart=d.cart; updateCartBadge(); renderCart(); toast('Added to cart. Total remains £0.00.'); } catch(e){toast(e.message,true);} }
  async function setCart(pid,qty){ try{const d=await api('/api/cart',{method:'POST',body:{productId:pid,action:'set',quantity:qty}});state.cart=d.cart;updateCartBadge();renderCart();}catch(e){toast(e.message,true);} }
  async function toggleFavourite(pid){ try{const d=await api(`/api/favourites/${encodeURIComponent(pid)}`,{method:'POST'}); if(d.favourite&&!state.favourites.includes(pid))state.favourites.push(pid); if(!d.favourite)state.favourites=state.favourites.filter(x=>x!==pid); if(routeName()==='shop')renderShop(); if($('#productDialog').open){$('#productDialog').close();openProduct(pid);} }catch(e){toast(e.message,true);} }
  function openCart(){renderCart();$('#drawerBackdrop').hidden=false;$('#cartDrawer').classList.add('open');$('#cartDrawer').setAttribute('aria-hidden','false');}
  function closeCart(){ $('#drawerBackdrop').hidden=true;$('#cartDrawer').classList.remove('open');$('#cartDrawer').setAttribute('aria-hidden','true'); }
  function renderCart(){ const h=$('#cartItems'); if(!state.cart.length){h.innerHTML=empty('🛒','Your cart is aggressively empty','Add something. It is literally free.');$('#checkoutBtn').disabled=true;return;} $('#checkoutBtn').disabled=false; h.innerHTML=state.cart.map(i=>`<div class="cart-item"><div class="cart-item-emoji">${i.emoji}</div><div><h4>${escapeHTML(i.name)}</h4><span class="muted tiny">£0.00 each</span></div><div class="qty"><button type="button" data-cart="minus" data-id="${escapeAttr(i.id)}">−</button><strong>${i.qty}</strong><button type="button" data-cart="plus" data-id="${escapeAttr(i.id)}">+</button></div></div>`).join(''); }
  function openCheckout(){ if(!state.cart.length)return; closeCart(); $('#checkoutName').value=state.user.displayName; $('#checkoutSummary').innerHTML=`<strong>${cartQty()} item(s)</strong><div class="muted tiny">${state.cart.map(i=>`${escapeHTML(i.name)} × ${i.qty}`).join(' · ')}</div><div class="totals" style="margin-top:10px"><span>Order total</span><strong class="zero-total">£0.00</strong></div>`; $('#termsCheck').checked=false; $('#checkoutDialog').showModal(); }
  async function placeOrder(e){e.preventDefault();if(!e.currentTarget.reportValidity())return;const btn=e.submitter;setButtonBusy(btn,true,'Placing free order…');try{const d=await api('/api/orders/checkout',{method:'POST',body:{customerName:$('#checkoutName').value,deliveryMethod:$('#deliveryMethod').value,deliveryNotes:$('#deliveryNotes').value}});state.cart=d.cart;state.loyalty=d.loyalty;state.orders.unshift(d.order);$('#checkoutDialog').close();updateCartBadge();confetti(28);toast(`${d.order.order_number} placed. +5 Yaya Points.`);location.hash='#orders';}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Place order — £0.00');}}

  function renderLoyalty(){ const l=state.loyalty; if(!l)return; const person=loyaltyPerson(); const tier=tierInfo(l.balance); const adminView=state.user.role==='admin'&&ui.loyaltyTarget!==state.user.id; const claims=new Set((l.claims||[]).map(c=>`${c.rule_id}|${c.period_key}`));
    view.innerHTML=`<section class="page"><div class="page-head"><div><p class="eyebrow">Yaya Rewards Club</p><h1>${escapeHTML(person?.displayName||'Yaya')} Loyalty</h1><p>Every point in and out is recorded. No mysterious balance changes and no awarding yourself 500 points for eating watermelon.</p></div><div class="page-actions">${state.user.role==='admin'?memberSelector():''}<a class="secondary" href="/api/export/loyalty.csv${adminView?`?userId=${encodeURIComponent(ui.loyaltyTarget)}`:''}" download>Export CSV</a></div></div>
    <div class="loyalty-hero"><div class="points-card"><span class="points-label">Current balance</span><strong class="points-number">${l.balance}</strong><span>Yaya Points</span><div class="tier-line"><span>${tier.current.emoji} ${escapeHTML(tier.current.name)}</span><span>${tier.next?`${tier.next.min-l.balance} to ${tier.next.name}`:'Maximum menace achieved'}</span></div><div class="progress"><i style="width:${tier.progress}%"></i></div></div><div class="loyalty-side">${stat('Total earned',l.earned,'points credited')}${stat('Total spent',l.spent,'points redeemed')}</div></div>
    ${adminView?`<div class="info-box">You are viewing ${escapeHTML(person?.displayName||'member')} as administrator. Claims and reward redemptions are done from the member account; you can make recorded adjustments in Admin.</div>`:''}
    <section class="section"><div class="section-head"><h2>Earn points</h2><span class="muted tiny">Claim rules enforce daily, weekly and one-time limits.</span></div><div class="cards-3">${l.earnRules.map(r=>{const used=claimUsed(r,claims);return`<div class="card"><div class="big-icon">${r.emoji}</div><h3>${escapeHTML(r.name)}</h3><p>${escapeHTML(r.description)}</p><div class="points-pill">+${r.points} points</div>${adminView?'<button class="secondary full" disabled>Member claim only</button>':`<button class="primary full" type="button" data-action="claim" data-id="${escapeAttr(r.id)}" ${used?'disabled':''}>${used?'Claimed for this period':`Claim +${r.points}`}</button>`}</div>`;}).join('')}</div></section>
    <section class="section"><div class="section-head"><h2>Rewards</h2></div><div class="reward-grid">${l.rewards.map(r=>`<div class="reward-card"><div class="big-icon">${r.emoji}</div><h3>${escapeHTML(r.name)}</h3><p>${escapeHTML(r.description)}</p><div class="reward-cost">${r.cost} points</div>${adminView?'<button class="secondary full" disabled>Member redeem only</button>':`<button class="primary full" type="button" data-action="redeem" data-id="${escapeAttr(r.id)}" ${l.balance<r.cost?'disabled':''}>Redeem</button>`}</div>`).join('')}</div></section>
    <section class="section"><div class="section-head"><h2>Badges</h2></div><div class="badges">${l.badges.map(b=>`<div class="badge-card ${b.awarded_at?'earned':''}"><span>${b.awarded_at?b.emoji:'🔒'}</span><div><strong>${escapeHTML(b.name)}</strong><small>${escapeHTML(b.description)}</small></div></div>`).join('')}</div></section>
    <section class="section"><div class="section-head"><h2>Redemptions</h2></div><div class="review-history">${l.redemptions.length?l.redemptions.map(r=>`<div class="review-entry"><div class="order-top"><div><strong>${r.emoji} ${escapeHTML(r.name)}</strong><div class="muted tiny">${r.cost} points · ${fmtDate(r.redeemed_at)}</div></div><span class="status ${r.status==='Used'?'delivered':''}">${escapeHTML(r.status)}</span></div>${r.status==='Redeemed'&&!adminView?`<button class="secondary" type="button" data-action="use-redemption" data-id="${escapeAttr(r.id)}">Mark used</button>`:''}</div>`).join(''):empty('🎟️','No redemptions yet','The points are being hoarded responsibly.')}</div></section>
    <section class="section"><div class="section-head"><h2>Points history</h2></div><div class="transaction-list">${l.transactions.length?l.transactions.map(txRow).join(''):empty('🧾','No transactions yet','The first earn or shop order will start the ledger.')}</div></section></section>`;
    $('#loyaltyMember')?.addEventListener('change',async e=>{ui.loyaltyTarget=e.target.value;try{const d=await api(`/api/loyalty?userId=${encodeURIComponent(ui.loyaltyTarget)}`);state.loyalty=d.loyalty;renderLoyalty();}catch(err){toast(err.message,true);}});
  }
  function memberSelector(){ const ms=state.admin?.users?.filter(u=>u.role==='member')||[]; return `<select id="loyaltyMember" aria-label="Member loyalty account">${ms.map(m=>`<option value="${escapeAttr(m.id)}" ${m.id===ui.loyaltyTarget?'selected':''}>${escapeHTML(m.display_name)}</option>`).join('')}</select>`; }
  function tierInfo(balance){ const tiers=state.tiers?.length?state.tiers:[{name:'Bronze Duck',min:0,emoji:'🦆'}]; let current=tiers[0],next=null; for(let i=0;i<tiers.length;i++){if(balance>=tiers[i].min)current=tiers[i];else{next=tiers[i];break;}} const prev=current.min; const progress=next?Math.max(0,Math.min(100,((balance-prev)/(next.min-prev))*100)):100; return{current,next,progress}; }
  function claimUsed(rule,claims){ if(rule.frequency==='unlimited')return false; const now=new Date(); const daily=now.toISOString().slice(0,10); if(rule.frequency==='daily')return claims.has(`${rule.id}|${daily}`); if(rule.frequency==='once')return claims.has(`${rule.id}|once`); if(rule.frequency==='weekly')return [...claims].some(x=>x.startsWith(`${rule.id}|`)&&x.includes(weekKey(now))); return false; }
  function weekKey(d){ const x=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate())); const day=x.getUTCDay()||7;x.setUTCDate(x.getUTCDate()+4-day);const y0=new Date(Date.UTC(x.getUTCFullYear(),0,1));const w=Math.ceil((((x-y0)/86400000)+1)/7);return `${x.getUTCFullYear()}-W${String(w).padStart(2,'0')}`; }
  function txRow(t){ return `<div class="transaction-item"><div class="tx-icon">${t.delta>0?'⭐':t.type==='adjustment'?'🛠️':'🎟️'}</div><div class="tx-copy"><strong>${escapeHTML(t.label)}</strong><small>${escapeHTML(t.note||t.reference_type||'Loyalty')} · ${fmtDate(t.created_at)}</small></div><div class="tx-amount ${t.delta>0?'positive':'negative'}"><strong>${signed(t.delta)}</strong><small>bal ${t.balance_after}</small></div></div>`; }
  async function claimRule(id){ try{const d=await api('/api/loyalty/claim',{method:'POST',body:{ruleId:id}});state.loyalty=d.loyalty;confetti(20);toast('Yaya Points added to the ledger.');renderLoyalty();}catch(e){toast(e.message,true);} }
  async function redeem(id){ const r=state.loyalty.rewards.find(x=>x.id===id); if(!r)return; if(!confirm(`Redeem ${r.name} for ${r.cost} Yaya Points?`))return;try{const d=await api('/api/loyalty/redeem',{method:'POST',body:{rewardId:id}});state.loyalty=d.loyalty;confetti(16);toast(`${r.name} redeemed.`);renderLoyalty();}catch(e){toast(e.message,true);} }
  async function markUsed(id){try{const d=await api(`/api/loyalty/redemptions/${encodeURIComponent(id)}/use`,{method:'POST'});if(d.loyalty)state.loyalty=d.loyalty;toast('Reward marked as used.');renderLoyalty();}catch(e){toast(e.message,true);} }

  function renderOrders(){ const rows=state.orders||[]; view.innerHTML=`<section class="page"><div class="page-head"><div><p class="eyebrow">Fulfilment centre</p><h1>${state.user.role==='admin'?'All orders':'Order history'}</h1><p>Every £0.00 purchase gets an order number, status trail and proper record.</p></div><div class="page-actions"><a class="secondary" href="/api/export/orders.csv" download>Export CSV</a><button class="ghost" type="button" data-action="refresh">Refresh</button></div></div><div class="orders-list">${rows.length?rows.map(orderCard).join(''):empty('📦','No orders yet','Go spend absolutely nothing in the shop.')}</div></section>`; }
  function orderCard(o){return `<article class="order-card"><div class="order-top"><div><p class="eyebrow">${escapeHTML(o.source==='room-service'?'Room Service':'£0 Shop')}</p><h3>${escapeHTML(o.order_number)}</h3><div class="muted tiny">${fmtDate(o.created_at)}${o.display_name?` · ${escapeHTML(o.display_name)}`:''}</div></div><span class="status ${o.status==='Delivered'?'delivered':''}">${escapeHTML(o.status)}</span></div><div class="order-items">${o.items.map(i=>`<span>${i.item_emoji} ${escapeHTML(i.item_name)} × ${i.quantity}</span>`).join('')}</div><div class="order-actions"><strong class="zero-total">£0.00</strong><button class="secondary" type="button" data-action="order-detail" data-id="${escapeAttr(o.id)}">View tracking</button>${o.source==='shop'?`<button class="ghost" type="button" data-action="reorder" data-id="${escapeAttr(o.id)}">Re-order</button>`:''}${state.user.role==='admin'&&!['Delivered','Cancelled'].includes(o.status)?`<button class="primary" type="button" data-action="admin-status" data-id="${escapeAttr(o.id)}">Update status</button>`:''}</div></article>`;}
  async function openOrder(id){try{const d=await api(`/api/orders/${encodeURIComponent(id)}`);const o=d.order;$('#detailDialogContent').innerHTML=`<div class="modal-body"><div class="modal-head"><div><p class="eyebrow">Order tracking</p><h2>${escapeHTML(o.order_number)}</h2></div><button class="icon-btn dialog-close" type="button">✕</button></div><div class="detail-summary"><span>${fmtDate(o.created_at)}</span><strong class="zero-total">£0.00</strong></div><div class="order-items">${o.items.map(i=>`<span>${i.item_emoji} ${escapeHTML(i.item_name)} × ${i.quantity}</span>`).join('')}</div><h3>Status history</h3><div class="timeline">${o.statusHistory.map(h=>`<div class="timeline-item"><span class="timeline-dot"></span><div><strong>${escapeHTML(h.status)}</strong><small>${fmtDate(h.created_at)}${h.actor_name?` · ${escapeHTML(h.actor_name)}`:''}${h.note?` · ${escapeHTML(h.note)}`:''}</small></div></div>`).join('')}</div><div class="info-box"><strong>Delivery:</strong> ${escapeHTML(o.delivery_method)}${o.delivery_notes?`<br><strong>Notes:</strong> ${escapeHTML(o.delivery_notes)}`:''}</div></div>`;$('#detailDialog').showModal();}catch(e){toast(e.message,true);} }
  async function reorder(id){try{const d=await api(`/api/orders/${encodeURIComponent(id)}/reorder`,{method:'POST'});state.cart=d.cart;updateCartBadge();toast('Items returned to cart. The price remains suspiciously unchanged.');openCart();}catch(e){toast(e.message,true);} }
  async function openStatusEditor(id){let o=state.orders.find(x=>x.id===id)||state.admin?.openOrders?.find(x=>x.id===id);if(!o){try{const d=await api(`/api/orders/${encodeURIComponent(id)}`);o=d.order;}catch(err){toast(err.message,true);return;}}$('#detailDialogContent').innerHTML=`<form class="modal-body" id="statusForm"><div class="modal-head"><div><p class="eyebrow">Bear fulfilment control</p><h2>${escapeHTML(o.order_number)}</h2></div><button class="icon-btn dialog-close" type="button">✕</button></div><label>Status<select id="statusValue">${ORDER_STATUSES.map(s=>`<option ${s===o.status?'selected':''}>${escapeHTML(s)}</option>`).join('')}</select></label><label>Tracking note<textarea id="statusNote" rows="3" maxlength="200" placeholder="Optional note for the customer"></textarea></label><button class="primary full" type="submit">Save tracking update</button></form>`;$('#detailDialog').showModal();$('#statusForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true);try{const d=await api(`/api/orders/${encodeURIComponent(id)}/status`,{method:'POST',body:{status:$('#statusValue').value,note:$('#statusNote').value}});const ix=state.orders.findIndex(x=>x.id===id);if(ix>=0)state.orders[ix]={...state.orders[ix],...d.order};if(state.admin?.openOrders){const ax=state.admin.openOrders.findIndex(x=>x.id===id);if(ax>=0)state.admin.openOrders[ax]={...state.admin.openOrders[ax],...d.order};}$('#detailDialog').close();toast('Order tracking updated.');if(location.hash==='#admin')renderAdmin();else renderOrders();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Save tracking update');}});}

  function renderFun(){const tabs=[['dates','🎡','Date Roulette'],['room','🍳','Room Service'],['memories','📸','Memories'],['reviews','⭐','Reviews'],['complaints','📣','Complaints'],['adventures','🗺️','Adventures']];view.innerHTML=`<section class="page"><div class="page-head"><div><p class="eyebrow">Non-essential critical services</p><h1>Fun Stuff</h1><p>The department responsible for dates, food, memories, customer feedback and bad ideas.</p></div></div><div class="tabs fun-tabs">${tabs.map(([id,em,l])=>`<button class="tab-btn ${ui.funTab===id?'active':''}" type="button" data-action="fun-tab" data-id="${id}">${em} ${l}</button>`).join('')}</div><div id="funPanel">${renderFunPanel()}</div></section>`; bindFunForm();}
  function renderFunPanel(){if(ui.funTab==='dates')return funDates();if(ui.funTab==='room')return funRoom();if(ui.funTab==='memories')return funMemories();if(ui.funTab==='reviews')return funReviews();if(ui.funTab==='complaints')return funComplaints();return funAdventures();}
  function funDates(){const r=ui.roulette;return `<div class="cards-2"><div class="fun-card"><p class="eyebrow">Decision avoidance technology</p><h2>Date Roulette</h2><p>Press the button and let a highly unqualified algorithm decide what happens.</p><div class="roulette-result">${r?`<div class="big-icon">${r.emoji}</div><h3>${escapeHTML(r.title)}</h3><p>${escapeHTML(r.detail)}</p>`:'<div class="big-icon">🎡</div><h3>Ready to make a questionable decision?</h3>'}</div><div class="dialog-actions"><button class="primary" type="button" data-action="spin-date">Spin</button>${r?'<button class="secondary" type="button" data-action="save-date">Save this date</button>':''}</div></div><div class="fun-card"><h2>Saved dates</h2><div class="review-history">${state.fun.dates.length?state.fun.dates.map(d=>`<div class="review-entry"><strong>❤️ ${escapeHTML(d.title)}</strong><div class="muted tiny">${escapeHTML(d.detail)} · ${fmtDate(d.created_at)}</div></div>`).join(''):empty('❤️','Nothing saved','Spin something ridiculous.')}</div></div></div>`;}
  function funRoom(){return `<div class="cards-2"><form class="fun-card" id="roomForm"><p class="eyebrow">Bear Hospitality Group</p><h2>Breakfast Room Service</h2><p>Tick the required items. Accounting has waived the entire bill again.</p><div class="room-menu">${state.roomServiceMenu.map(m=>`<label class="menu-check"><input type="checkbox" name="roomItem" value="${escapeAttr(m.id)}"><span>${m.emoji} ${escapeHTML(m.name)}</span><input class="menu-qty" type="number" min="1" max="5" value="1" data-room-qty="${escapeAttr(m.id)}" aria-label="Quantity"></label>`).join('')}</div><label>Special instructions<textarea id="roomNotes" rows="3" maxlength="300" placeholder="No pork, no raw onion, extra dramatic presentation…"></textarea></label><button class="primary full" type="submit">Place room-service order — £0.00</button></form><div class="fun-card"><h2>Room Service benefits</h2><div class="feature-stack"><span>🍽️ Appears in proper order history</span><span>⭐ +5 Yaya Points at checkout</span><span>📦 Bear can update the delivery status</span><span>💷 Final invoice: £0.00</span></div></div></div>`;}
  function funMemories(){return `<div class="cards-2"><form class="fun-card" id="memoryForm"><p class="eyebrow">Private R2 memory vault</p><h2>Add a memory</h2><label>Title<input id="memoryTitle" maxlength="120" required placeholder="What happened?" /></label><label>Date<input id="memoryDate" type="date" /></label><label>Mood<select id="memoryMood"><option>💚</option><option>😂</option><option>🥰</option><option>🦆</option><option>🐻</option><option>🦈</option><option>🦙</option></select></label><label>Story<textarea id="memoryBody" rows="4" maxlength="3000"></textarea></label><label class="file-button">Photo, video or PDF<input id="memoryFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,application/pdf"></label><small class="muted">Maximum 8 MB. Files stay in the private R2 bucket and are served through the logged-in Worker.</small><button class="primary full" type="submit">Save memory</button></form><div class="fun-card memory-panel"><h2>Memory wall</h2><div class="memory-grid">${state.fun.memories.length?state.fun.memories.map(memoryCard).join(''):empty('📸','No memories yet','Add the first one.')}</div></div></div>`;}
  function memoryCard(m){let media='';if(m.attachment_key){const u=`/media/${encodeURI(m.attachment_key).replaceAll('#','%23')}`;if((m.attachment_type||'').startsWith('image/'))media=`<img src="${escapeAttr(u)}" alt="${escapeAttr(m.title)}" loading="lazy">`;else if((m.attachment_type||'').startsWith('video/'))media=`<video controls preload="metadata" src="${escapeAttr(u)}"></video>`;else media=`<a class="secondary" href="${escapeAttr(u)}" target="_blank">Open attachment</a>`;}return `<article class="memory-card">${media}<div class="memory-copy"><span class="big-icon small">${escapeHTML(m.mood)}</span><h3>${escapeHTML(m.title)}</h3><p>${escapeHTML(m.body||'')}</p><small>${m.happened_on?escapeHTML(m.happened_on):fmtDate(m.created_at,false)}</small>${state.user.role==='admin'||m.user_id===state.user.id?`<button class="ghost tiny-btn" type="button" data-action="delete-memory" data-id="${escapeAttr(m.id)}">Delete</button>`:''}</div></article>`;}
  function funReviews(){return `<div class="cards-2"><form class="fun-card" id="reviewForm"><p class="eyebrow">Independent quality assurance</p><h2>Monthly Review</h2><label>Rating<select id="reviewRating"><option value="5">⭐⭐⭐⭐⭐ — Outstanding</option><option value="4">⭐⭐⭐⭐ — Acceptable Bear</option><option value="3">⭐⭐⭐ — Formal review needed</option><option value="2">⭐⭐ — Management intervention</option><option value="1">⭐ — Catastrophic</option></select></label><label>Headline<input id="reviewTitle" maxlength="120" placeholder="e.g. Bear performance improved after snacks" /></label><label>Comments<textarea id="reviewBody" rows="5" maxlength="2000" required></textarea></label><button class="primary full" type="submit">Submit official review</button></form><div class="fun-card"><h2>Review archive</h2><div class="review-history">${state.fun.reviews.length?state.fun.reviews.map(r=>`<div class="review-entry"><strong>${'⭐'.repeat(r.rating)} ${escapeHTML(r.title||'Monthly review')}</strong><p>${escapeHTML(r.body)}</p><small>${fmtDate(r.created_at)}</small></div>`).join(''):empty('⭐','No reviews filed','Customer satisfaction remains technically unmeasured.')}</div></div></div>`;}
  function funComplaints(){return `<div class="cards-2"><form class="fun-card" id="complaintForm"><p class="eyebrow">Duck & Bear Customer Services</p><h2>Formal Complaint</h2><label>Category<select id="complaintCategory"><option>Other serious incident</option><option>Food theft</option><option>Bear misconduct</option><option>Insufficient cuddles</option><option>Remote-control dispute</option><option>Unreasonable levels of nonsense</option></select></label><label>What happened?<textarea id="complaintBody" rows="5" maxlength="2500" required></textarea></label><label>Compensation required<textarea id="complaintComp" rows="3" maxlength="800"></textarea></label><button class="primary full" type="submit">Open a case</button></form><div class="fun-card"><h2>Case history</h2><div class="review-history">${state.fun.complaints.length?state.fun.complaints.map(c=>`<div class="complaint-ticket"><div class="order-top"><div><strong>${escapeHTML(c.case_number)}</strong><div class="muted tiny">${escapeHTML(c.category)} · ${fmtDate(c.created_at)}</div></div><span class="status">${escapeHTML(c.status)}</span></div><p>${escapeHTML(c.body)}</p>${c.compensation_requested?`<small><strong>Requested:</strong> ${escapeHTML(c.compensation_requested)}</small>`:''}${c.resolution?`<div class="info-box"><strong>Management response:</strong> ${escapeHTML(c.resolution)}</div>`:''}</div>`).join(''):empty('📣','No complaints','This seems statistically unlikely.')}</div></div></div>`;}
  function funAdventures(){return `<div class="cards-2"><form class="fun-card" id="adventureForm"><p class="eyebrow">Adventure pipeline</p><h2>Suggest something</h2><label>Adventure<input id="adventureTitle" maxlength="120" required placeholder="Scuba diving, weird restaurant, animal encounter…" /></label><label>Notes<textarea id="adventureDetail" rows="4" maxlength="1000"></textarea></label><button class="primary full" type="submit">Add adventure</button></form><div class="fun-card"><h2>Adventure list</h2><div class="review-history">${state.fun.adventures.length?state.fun.adventures.map(a=>`<div class="review-entry"><div class="order-top"><div><strong>${a.status==='Completed'?'✅':'🗺️'} ${escapeHTML(a.title)}</strong><div class="muted tiny">${escapeHTML(a.detail)} · ${escapeHTML(a.status)}</div></div>${a.status!=='Completed'?`<button class="secondary" type="button" data-action="complete-adventure" data-id="${escapeAttr(a.id)}">Complete +50</button>`:'<span class="status delivered">Completed</span>'}</div></div>`).join(''):empty('🗺️','No adventures added','This is clearly unacceptable.')}</div></div></div>`;}
  function bindFunForm(){if(ui.funTab==='room')$('#roomForm')?.addEventListener('submit',submitRoom);if(ui.funTab==='memories')$('#memoryForm')?.addEventListener('submit',submitMemory);if(ui.funTab==='reviews')$('#reviewForm')?.addEventListener('submit',submitReview);if(ui.funTab==='complaints')$('#complaintForm')?.addEventListener('submit',submitComplaint);if(ui.funTab==='adventures')$('#adventureForm')?.addEventListener('submit',submitAdventure);}
  async function saveRoulette(){if(!ui.roulette)return;try{const d=await api('/api/fun/dates',{method:'POST',body:{title:ui.roulette.title,detail:ui.roulette.detail}});state.fun=d.fun;toast('Date saved to the relationship calendar-ish.');renderFun();}catch(e){toast(e.message,true);} }
  async function submitRoom(e){e.preventDefault();const items=$$('input[name="roomItem"]:checked').map(x=>({id:x.value,qty:Number($(`[data-room-qty="${CSS.escape(x.value)}"]`)?.value||1)}));if(!items.length){toast('Choose at least one breakfast item.',true);return;}const btn=e.submitter;setButtonBusy(btn,true,'Sending to Bear kitchen…');try{const d=await api('/api/fun/room-service',{method:'POST',body:{items,notes:$('#roomNotes').value}});state.orders.unshift(d.order);if(state.user.role!=='admin')state.loyalty=d.loyalty;confetti(18);toast(`${d.order.order_number} sent to Bear kitchen. +5 points.`);location.hash='#orders';}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Place room-service order — £0.00');}}
  async function submitMemory(e){e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true,'Saving memory…');try{let attachment=null;const file=$('#memoryFile').files?.[0];if(file){setButtonBusy(btn,true,'Uploading securely…');const fd=new FormData();fd.append('file',file);const up=await api('/api/media/upload',{method:'POST',body:fd});attachment=up.attachment;}const d=await api('/api/memories',{method:'POST',body:{title:$('#memoryTitle').value,body:$('#memoryBody').value,happenedOn:$('#memoryDate').value,mood:$('#memoryMood').value,attachment}});state.fun=d.fun;confetti(10);toast('Memory saved.');renderFun();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Save memory');}}
  async function submitReview(e){e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true);try{const d=await api('/api/fun/reviews',{method:'POST',body:{rating:Number($('#reviewRating').value),title:$('#reviewTitle').value,body:$('#reviewBody').value}});state.fun=d.fun;toast('Review filed with suspicious professionalism.');renderFun();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Submit official review');}}
  async function submitComplaint(e){e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true);try{const d=await api('/api/fun/complaints',{method:'POST',body:{category:$('#complaintCategory').value,body:$('#complaintBody').value,compensationRequested:$('#complaintComp').value}});state.fun=d.fun;toast(`Case ${d.caseNumber} opened. Management is pretending to investigate.`);renderFun();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Open a case');}}
  async function submitAdventure(e){e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true);try{const d=await api('/api/fun/adventures',{method:'POST',body:{title:$('#adventureTitle').value,detail:$('#adventureDetail').value}});state.fun=d.fun;toast('Adventure added to the highly official pipeline.');renderFun();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Add adventure');}}
  async function completeAdventure(id){try{const d=await api(`/api/fun/adventures/${encodeURIComponent(id)}/status`,{method:'POST',body:{status:'Completed'}});state.fun=d.fun;if(state.user.role!=='admin')state.loyalty=d.loyalty;confetti(24);toast('Adventure complete. +50 Yaya Points.');renderFun();}catch(e){toast(e.message,true);} }
  async function deleteMemory(id){if(!confirm('Delete this memory and its attachment?'))return;try{const d=await api(`/api/memories/${encodeURIComponent(id)}`,{method:'DELETE'});state.fun=d.fun;toast('Memory deleted.');renderFun();}catch(e){toast(e.message,true);} }

  function renderAdmin(){if(state.user.role!=='admin')return;const a=state.admin;const tabs=[['dashboard','📊','Dashboard'],['loyalty','⭐','Loyalty'],['orders','📦','Orders'],['catalog','🛍️','Catalog'],['rewards','🎟️','Rewards'],['complaints','📣','Complaints'],['audit','🧾','Audit']];view.innerHTML=`<section class="page"><div class="page-head"><div><p class="eyebrow">Bear Management Console</p><h1>Admin</h1><p>Changes here are recorded in the audit log. No silent points edits or mystery fulfilment.</p></div><button class="secondary" type="button" data-action="refresh-admin">Refresh</button></div><div class="tabs admin-tabs">${tabs.map(([id,em,l])=>`<button class="tab-btn ${ui.adminTab===id?'active':''}" type="button" data-action="admin-tab" data-id="${id}">${em} ${l}</button>`).join('')}</div><div id="adminPanel">${adminPanel()}</div></section>`;bindAdminForms();}
  function adminPanel(){const a=state.admin;if(ui.adminTab==='dashboard')return `<div class="stats-grid">${stat('Open orders',a.openOrders.length,'awaiting Bear action')}${stat('Open complaints',a.complaints.filter(c=>!String(c.status).toLowerCase().includes('closed')).length,'cases')}${stat('Products',a.products.filter(p=>p.active).length,'active in shop')}${stat('Members',a.memberBalances.length,'loyalty accounts')}</div><section class="section"><div class="section-head"><h2>Member balances</h2></div><div class="cards-3">${a.memberBalances.map(m=>`<div class="card"><div class="big-icon">💚</div><h3>${escapeHTML(m.displayName)}</h3><div class="points-number mini">${m.balance}</div><p>Yaya Points</p><button class="secondary full" type="button" data-action="admin-view-loyalty" data-id="${escapeAttr(m.userId)}">Open loyalty</button><button class="ghost full" type="button" data-action="admin-reset-password" data-id="${escapeAttr(m.userId)}">Reset password</button></div>`).join('')}</div></section>`;
    if(ui.adminTab==='loyalty')return adminLoyalty(); if(ui.adminTab==='orders')return `<div class="orders-list">${a.openOrders.length?a.openOrders.map(o=>`<article class="order-card"><div class="order-top"><div><h3>${escapeHTML(o.order_number)}</h3><div class="muted tiny">${escapeHTML(o.display_name)} · ${fmtDate(o.created_at)}</div></div><span class="status">${escapeHTML(o.status)}</span></div><div class="order-actions"><button class="primary" type="button" data-action="admin-status" data-id="${escapeAttr(o.id)}">Update tracking</button><button class="secondary" type="button" data-action="order-detail" data-id="${escapeAttr(o.id)}">View</button></div></article>`).join(''):empty('📦','No open orders','Bear fulfilment has achieved the impossible.')}</div>`;
    if(ui.adminTab==='catalog')return adminCatalog(); if(ui.adminTab==='rewards')return adminRewards(); if(ui.adminTab==='complaints')return adminComplaints(); return adminAuditPanel(); }
  function adminLoyalty(){const ms=state.admin.memberBalances;return `<div class="cards-2"><form class="fun-card" id="adjustForm"><p class="eyebrow">Audited adjustment</p><h2>Change a balance</h2><label>Member<select id="adjustUser">${ms.map(m=>`<option value="${escapeAttr(m.userId)}">${escapeHTML(m.displayName)} — ${m.balance} pts</option>`).join('')}</select></label><label>Points change<input id="adjustDelta" type="number" min="-100000" max="100000" step="1" required placeholder="e.g. 50 or -20" /></label><label>Reason<textarea id="adjustNote" rows="4" maxlength="500" required placeholder="e.g. Opening balance imported from Tally"></textarea></label><button class="primary full" type="submit">Record adjustment</button></form><div class="fun-card"><h2>How this works</h2><div class="feature-stack"><span>🧾 Every adjustment creates a transaction</span><span>👤 The admin actor is recorded</span><span>🕓 Date/time and resulting balance are stored</span><span>🚫 Balances cannot go below zero</span></div></div></div>`;}
  function adminCatalog(){return `<div class="section-head"><h2>Shop catalog</h2><button class="primary" type="button" data-action="new-product">+ Add product</button></div><div class="admin-list">${state.admin.products.map(p=>`<div class="admin-row"><div class="admin-row-icon">${p.emoji}</div><div><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.category)} · ${p.active?'Active':'Hidden'} · £0.00</small></div><div class="admin-row-actions"><button class="secondary" type="button" data-action="edit-product" data-id="${escapeAttr(p.id)}">Edit</button></div></div>`).join('')}</div>`;}
  function adminRewards(){return `<div class="section-head"><h2>Rewards & earn rules</h2><button class="primary" type="button" data-action="new-reward">+ Add reward</button></div><div class="admin-grid"><div><h3>Rewards</h3><div class="admin-list">${state.admin.rewards.map(r=>`<div class="admin-row"><div class="admin-row-icon">${r.emoji}</div><div><strong>${escapeHTML(r.name)}</strong><small>${r.cost} pts · ${r.active?'Active':'Hidden'}</small></div><button class="secondary" type="button" data-action="edit-reward" data-id="${escapeAttr(r.id)}">Edit</button></div>`).join('')}</div></div><div><h3>Earn rules</h3><div class="admin-list">${state.admin.earnRules.map(r=>`<div class="admin-row"><div class="admin-row-icon">${r.emoji}</div><div><strong>${escapeHTML(r.name)}</strong><small>+${r.points} · ${escapeHTML(r.frequency)} · ${r.active?'Active':'Hidden'}</small></div><button class="secondary" type="button" data-action="edit-earn" data-id="${escapeAttr(r.id)}">Edit</button></div>`).join('')}</div></div></div>`;}
  function adminComplaints(){return `<div class="admin-list">${state.admin.complaints.length?state.admin.complaints.map(c=>`<div class="admin-row complaint-admin"><div class="admin-row-icon">📣</div><div><strong>${escapeHTML(c.case_number)} · ${escapeHTML(c.display_name)}</strong><small>${escapeHTML(c.category)} · ${escapeHTML(c.status)} · ${fmtDate(c.created_at)}</small><p>${escapeHTML(c.body)}</p></div><button class="secondary" type="button" data-action="resolve-complaint" data-id="${escapeAttr(c.id)}">Respond</button></div>`).join(''):empty('📣','No complaints','An unprecedented period of peace.')}</div>`;}
  function adminAuditPanel(){return `<div class="audit-list">${(state.admin.audit||[]).length?(state.admin.audit||[]).map(x=>`<div class="transaction-item"><div class="tx-icon">🧾</div><div class="tx-copy"><strong>${escapeHTML(x.action)}</strong><small>${escapeHTML(x.actor_name||'System')} · ${escapeHTML(x.entity_type)}${x.entity_id?` · ${escapeHTML(x.entity_id)}`:''} · ${fmtDate(x.created_at)}</small></div></div>`).join(''):empty('🧾','No audit entries loaded','Refresh admin to load the trail.')}</div>`;}
  function bindAdminForms(){if(ui.adminTab==='loyalty')$('#adjustForm')?.addEventListener('submit',submitAdjustment);}
  async function refreshAdmin(){try{const d=await api('/api/admin/dashboard');state.admin={...d.admin,audit:d.audit};renderAdmin();toast('Admin data refreshed.');}catch(e){toast(e.message,true);} }
  async function submitAdjustment(e){e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true);try{const d=await api('/api/admin/loyalty/adjust',{method:'POST',body:{userId:$('#adjustUser').value,delta:Number($('#adjustDelta').value),note:$('#adjustNote').value}});state.admin=d.admin;if(ui.loyaltyTarget===$('#adjustUser').value)state.loyalty=d.loyalty;toast('Points adjustment recorded in the ledger.');renderAdmin();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Record adjustment');}}
  function productEditor(id=null){const p=id?state.admin.products.find(x=>x.id===id):null;$('#detailDialogContent').innerHTML=`<form class="modal-body" id="productForm"><div class="modal-head"><div><p class="eyebrow">Catalog management</p><h2>${p?'Edit product':'New £0 product'}</h2></div><button class="icon-btn dialog-close" type="button">✕</button></div><div class="form-grid"><label>Name<input id="prodName" value="${escapeAttr(p?.name||'')}" maxlength="120" required /></label><label>Emoji<input id="prodEmoji" value="${escapeAttr(p?.emoji||'🎁')}" maxlength="10" /></label><label>Category<input id="prodCategory" value="${escapeAttr(p?.category||'Essentials')}" maxlength="60" required /></label><label>Stock label<input id="prodStock" value="${escapeAttr(p?.stock_label||'In stock')}" maxlength="100" /></label><label class="span-2">Short description<textarea id="prodBlurb" rows="2" maxlength="240">${escapeHTML(p?.blurb||'')}</textarea></label><label class="span-2">Full description<textarea id="prodDesc" rows="4" maxlength="1500">${escapeHTML(p?.description||'')}</textarea></label><label>Rating<input id="prodRating" type="number" min="1" max="5" step="0.1" value="${p?.rating||5}" /></label><label>Sort order<input id="prodSort" type="number" min="0" max="9999" value="${p?.sort_order||100}" /></label><label class="checkbox"><input id="prodActive" type="checkbox" ${p?.active===0?'':'checked'}><span>Visible in shop</span></label><label class="checkbox"><input id="prodFeatured" type="checkbox" ${p?.featured?'checked':''}><span>Featured</span></label></div><button class="primary full" type="submit">${p?'Save product':'Create product'}</button></form>`;$('#detailDialog').showModal();$('#productForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true);const body={name:$('#prodName').value,emoji:$('#prodEmoji').value,category:$('#prodCategory').value,stockLabel:$('#prodStock').value,blurb:$('#prodBlurb').value,description:$('#prodDesc').value,rating:Number($('#prodRating').value),sortOrder:Number($('#prodSort').value),active:$('#prodActive').checked,featured:$('#prodFeatured').checked};try{const d=await api(p?`/api/admin/products/${encodeURIComponent(p.id)}`:'/api/admin/products',{method:p?'PUT':'POST',body});state.admin=d.admin;await refreshActiveCatalog();$('#detailDialog').close();toast(p?'Product updated.':'Product created.');renderAdmin();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,p?'Save product':'Create product');}});}
  async function refreshActiveCatalog(){const d=await api('/api/bootstrap');state.products=d.products;state.favourites=d.favourites;state.cart=d.cart;state.orders=d.orders;state.fun=d.fun;state.admin={...d.admin,audit:state.admin?.audit||[]};}
  function rewardEditor(id=null){const r=id?state.admin.rewards.find(x=>x.id===id):null;$('#detailDialogContent').innerHTML=`<form class="modal-body" id="rewardForm"><div class="modal-head"><div><p class="eyebrow">Rewards catalog</p><h2>${r?'Edit reward':'New reward'}</h2></div><button class="icon-btn dialog-close" type="button">✕</button></div><label>Name<input id="rewardName" value="${escapeAttr(r?.name||'')}" maxlength="120" required /></label><label>Emoji<input id="rewardEmoji" value="${escapeAttr(r?.emoji||'🎁')}" maxlength="10" /></label><label>Cost<input id="rewardCost" type="number" min="1" max="100000" value="${r?.cost||50}" required /></label><label>Description<textarea id="rewardDesc" rows="4" maxlength="1000">${escapeHTML(r?.description||'')}</textarea></label><label class="checkbox"><input id="rewardActive" type="checkbox" ${r?.active===0?'':'checked'}><span>Active</span></label><button class="primary full" type="submit">${r?'Save reward':'Create reward'}</button></form>`;$('#detailDialog').showModal();$('#rewardForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true);const body={name:$('#rewardName').value,emoji:$('#rewardEmoji').value,cost:Number($('#rewardCost').value),description:$('#rewardDesc').value,active:$('#rewardActive').checked,sortOrder:r?.sort_order||100};try{const d=await api(r?`/api/admin/rewards/${encodeURIComponent(r.id)}`:'/api/admin/rewards',{method:r?'PUT':'POST',body});state.admin=d.admin;$('#detailDialog').close();toast(r?'Reward updated.':'Reward created.');renderAdmin();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,r?'Save reward':'Create reward');}});}
  function earnEditor(id){const r=state.admin.earnRules.find(x=>x.id===id);if(!r)return;$('#detailDialogContent').innerHTML=`<form class="modal-body" id="earnForm"><div class="modal-head"><div><p class="eyebrow">Earning rule</p><h2>${escapeHTML(r.name)}</h2></div><button class="icon-btn dialog-close" type="button">✕</button></div><label>Name<input id="earnName" value="${escapeAttr(r.name)}" maxlength="120" required /></label><label>Emoji<input id="earnEmoji" value="${escapeAttr(r.emoji)}" maxlength="10" /></label><label>Points<input id="earnPoints" type="number" min="1" max="100000" value="${r.points}" /></label><label>Frequency<select id="earnFreq">${['daily','weekly','once','unlimited'].map(f=>`<option ${f===r.frequency?'selected':''}>${f}</option>`).join('')}</select></label><label>Description<textarea id="earnDesc" rows="3" maxlength="1000">${escapeHTML(r.description)}</textarea></label><label class="checkbox"><input id="earnActive" type="checkbox" ${r.active?'checked':''}><span>Active</span></label><button class="primary full" type="submit">Save earn rule</button></form>`;$('#detailDialog').showModal();$('#earnForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true);try{const d=await api(`/api/admin/earn-rules/${encodeURIComponent(id)}`,{method:'PUT',body:{name:$('#earnName').value,emoji:$('#earnEmoji').value,points:Number($('#earnPoints').value),frequency:$('#earnFreq').value,description:$('#earnDesc').value,active:$('#earnActive').checked,sortOrder:r.sort_order}});state.admin=d.admin;$('#detailDialog').close();toast('Earn rule updated.');renderAdmin();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Save earn rule');}});}
  function complaintEditor(id){const c=state.admin.complaints.find(x=>x.id===id);if(!c)return;$('#detailDialogContent').innerHTML=`<form class="modal-body" id="complaintAdminForm"><div class="modal-head"><div><p class="eyebrow">${escapeHTML(c.case_number)}</p><h2>Management response</h2></div><button class="icon-btn dialog-close" type="button">✕</button></div><div class="info-box"><strong>${escapeHTML(c.display_name)}</strong><br>${escapeHTML(c.body)}</div><label>Status<input id="complaintStatus" maxlength="80" value="${escapeAttr(c.status)}" /></label><label>Resolution / response<textarea id="complaintResolution" rows="6" maxlength="2000">${escapeHTML(c.resolution||'')}</textarea></label><button class="primary full" type="submit">Save response</button></form>`;$('#detailDialog').showModal();$('#complaintAdminForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;setButtonBusy(btn,true);try{const d=await api(`/api/admin/complaints/${encodeURIComponent(id)}`,{method:'PUT',body:{status:$('#complaintStatus').value,resolution:$('#complaintResolution').value}});state.admin=d.admin;$('#detailDialog').close();toast('Complaint response saved.');renderAdmin();}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Save response');}});}

  function bindShell(){
    window.addEventListener('hashchange',()=>state.user&&render());
    view.addEventListener('click',handleAction);
    $('#cartBtn').addEventListener('click',openCart); $('#closeCartBtn').addEventListener('click',closeCart); $('#drawerBackdrop').addEventListener('click',closeCart); $('#checkoutBtn').addEventListener('click',openCheckout); $('#checkoutForm').addEventListener('submit',placeOrder); $('#themeBtn').addEventListener('click',cycleTheme); $('#profileBtn').addEventListener('click',openAccount); $('#logoutBtn').addEventListener('click',signOut); $('#eggClose').addEventListener('click',()=>$('#eggOverlay').hidden=true);
    $('#cartItems').addEventListener('click',e=>{const b=e.target.closest('[data-cart]');if(!b)return;const item=state.cart.find(x=>x.id===b.dataset.id);if(!item)return;setCart(item.id,item.qty+(b.dataset.cart==='plus'?1:-1));});
    $$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close();}));
    document.addEventListener('click',e=>{if(e.target.closest('[data-close-account]')&&$('#dataDialog')?.open)$('#dataDialog').close();const c=e.target.closest('.dialog-close');if(c)c.closest('dialog')?.close();if(e.target.closest('.zero-total')){ui.zeroClicks++;if(ui.zeroClicks===5)showEgg('egg-zero','💸','FINANCE HAS CHECKED','After five separate audits the total remains £0.00. No further action required.');}});
    $('#brandEgg').addEventListener('click',e=>{if(!state.user)return;ui.brandClicks++;if(ui.brandClicks===7)showEgg('egg-brand','🦆🕵️🐻','EXECUTIVE DUCK PROTOCOL','Seven taps have granted you clearance to absolutely nothing useful.');});
    $('#durianEgg').addEventListener('click',()=>{if(!state.user)return;ui.greenClicks++;if(ui.greenClicks===5)showEgg('egg-green','💚🍈','GREEN BUTTON SOCIETY','You found the suspicious green protocol. Durian-related decisions are now beyond management control.');});
    bindKonami();
  }

  async function handleAction(e){const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='retry-boot')boot();else if(a==='account')openAccount();else if(a==='open-cart')openCart();else if(a==='product')openProduct(id);else if(a==='add-cart')addCart(id);else if(a==='favourite')toggleFavourite(id);else if(a==='favourites-only'){ui.shopQuery='';ui.shopCategory='All';const favs=state.products.filter(p=>state.favourites.includes(p.id));view.innerHTML=`<section class="page"><div class="page-head"><div><p class="eyebrow">Saved for later</p><h1>Favourites</h1></div><a class="secondary" href="#shop">Back</a></div><div class="product-grid">${favs.length?favs.map(productCard).join(''):empty('♥','No favourites','Tap a heart in the shop.')}</div></section>`;}else if(a==='claim')claimRule(id);else if(a==='redeem')redeem(id);else if(a==='use-redemption')markUsed(id);else if(a==='order-detail')openOrder(id);else if(a==='reorder')reorder(id);else if(a==='admin-status')openStatusEditor(id);else if(a==='refresh'){try{await reloadAll();toast('Synced.');}catch(err){toast(err.message,true);}}else if(a==='fun-tab'){ui.funTab=id;renderFun();}else if(a==='spin-date'){ui.roulette=state.dateIdeas[Math.floor(Math.random()*state.dateIdeas.length)];renderFun();confetti(8);}else if(a==='save-date')saveRoulette();else if(a==='complete-adventure')completeAdventure(id);else if(a==='delete-memory')deleteMemory(id);else if(a==='admin-tab'){ui.adminTab=id;renderAdmin();}else if(a==='refresh-admin')refreshAdmin();else if(a==='admin-view-loyalty'){ui.loyaltyTarget=id;location.hash='#loyalty';const d=await api(`/api/loyalty?userId=${encodeURIComponent(id)}`);state.loyalty=d.loyalty;renderLoyalty();}else if(a==='admin-reset-password')adminResetPasswordEditor(id);else if(a==='new-product')productEditor();else if(a==='edit-product')productEditor(id);else if(a==='new-reward')rewardEditor();else if(a==='edit-reward')rewardEditor(id);else if(a==='edit-earn')earnEditor(id);else if(a==='resolve-complaint')complaintEditor(id);}

  function openAccount(){if(!state.user)return;$('#accountSummary').innerHTML=`<div class="account-card"><span class="account-avatar">${state.user.role==='admin'?'🐻':'🦆'}</span><div><strong>${escapeHTML(state.user.displayName)}</strong><small>@${escapeHTML(state.user.username)} · ${escapeHTML(state.user.role)}</small></div></div><p class="muted tiny">Orders, points and shared history are stored in Cloudflare D1. Memory uploads are private in R2 and require a signed-in session to view.</p><button class="secondary full" id="changePasswordBtn" type="button">Change password</button>${state.user.role==='admin'?'<a class="secondary full" href="#admin" data-close-account>Open Admin Console</a>':''}`;$('#changePasswordBtn').addEventListener('click',()=>{$('#dataDialog').close();passwordEditor();});$('#dataDialog').showModal();}
  function passwordEditor(){$('#detailDialogContent').innerHTML=`<form class="modal-body" id="passwordForm"><div class="modal-head"><div><p class="eyebrow">Account security</p><h2>Change password</h2></div><button class="icon-btn dialog-close" type="button">✕</button></div><label>Current password<input id="currentPassword" type="password" minlength="8" maxlength="128" autocomplete="current-password" required /></label><label>New password<input id="newPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required /></label><label>Confirm new password<input id="confirmPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required /></label><p class="muted tiny">Changing your password signs out your other sessions but keeps this device signed in.</p><button class="primary full" type="submit">Change password</button></form>`;$('#detailDialog').showModal();$('#passwordForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter,next=$('#newPassword').value;if(next!==$('#confirmPassword').value){toast('New passwords do not match.',true);return;}setButtonBusy(btn,true);try{await api('/api/account/password',{method:'POST',body:{currentPassword:$('#currentPassword').value,newPassword:next}});$('#detailDialog').close();toast('Password changed. Other sessions have been signed out.');}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Change password');}});}
  function adminResetPasswordEditor(id){const member=state.admin?.memberBalances?.find(x=>x.userId===id);if(!member)return;$('#detailDialogContent').innerHTML=`<form class="modal-body" id="resetPasswordForm"><div class="modal-head"><div><p class="eyebrow">Member account</p><h2>Reset ${escapeHTML(member.displayName)}'s password</h2></div><button class="icon-btn dialog-close" type="button">✕</button></div><div class="info-box">This signs the member out on every device. Their orders, points and history are not changed.</div><label>New password<input id="resetPassword" type="password" minlength="8" maxlength="128" autocomplete="new-password" required /></label><label>Confirm password<input id="resetPasswordConfirm" type="password" minlength="8" maxlength="128" autocomplete="new-password" required /></label><button class="primary full" type="submit">Reset member password</button></form>`;$('#detailDialog').showModal();$('#resetPasswordForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter,next=$('#resetPassword').value;if(next!==$('#resetPasswordConfirm').value){toast('Passwords do not match.',true);return;}setButtonBusy(btn,true);try{await api(`/api/admin/users/${encodeURIComponent(id)}/password`,{method:'POST',body:{newPassword:next}});$('#detailDialog').close();toast(`${member.displayName}'s password was reset and their sessions were signed out.`);}catch(err){toast(err.message,true);}finally{setButtonBusy(btn,false,'Reset member password');}});}

  async function signOut(){try{await api('/api/auth/logout',{method:'POST'});}catch{}state.user=null;state.products=[];state.cart=[];state.orders=[];state.loyalty=null;$('#dataDialog').close();closeCart();renderLogin();toast('Signed out.');}

  function setTheme(theme,persist=true){const t=THEMES.includes(theme)?theme:'system';document.documentElement.dataset.theme=t;$('#themeBtn').title=`Theme: ${t}`;const meta=$('meta[name="theme-color"]');if(meta)meta.content=t==='dark'?'#111311':'#f7efe7';if(persist)localStorage.setItem('duckBear.theme',t);}
  function cycleTheme(){const current=document.documentElement.dataset.theme||'system';const next=THEMES[(THEMES.indexOf(current)+1)%THEMES.length];setTheme(next);toast(`Theme: ${next}`);}
  function registerPwa(){if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();ui.deferredInstall=e;$('#installBtn').hidden=false;});$('#installBtn').addEventListener('click',async()=>{if(!ui.deferredInstall)return;ui.deferredInstall.prompt();await ui.deferredInstall.userChoice;ui.deferredInstall=null;$('#installBtn').hidden=true;});}
  function bindKonami(){const seq=['ArrowUp','ArrowUp','ArrowDown','ArrowDown','ArrowLeft','ArrowRight','ArrowLeft','ArrowRight','b','a'];let pos=0;document.addEventListener('keydown',e=>{if(!state.user||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(k===seq[pos]){pos++;if(pos===seq.length){pos=0;showEgg('egg-konami','🕹️🐻','CLASSIFIED BEAR CLEARANCE','Ancient keyboard ritual accepted. Nobody knows why this still works.');}}else pos=0;});}
  async function showEgg(badgeId,emoji,title,text){$('#eggEmoji').textContent=emoji;$('#eggTitle').textContent=title;$('#eggText').textContent=text;$('#eggOverlay').hidden=false;confetti(34);if(['egg-brand','egg-green','egg-konami'].includes(badgeId))api(`/api/badges/${badgeId}/unlock`,{method:'POST'}).catch(()=>{});}
  function toast(msg,bad=false){const el=$('#toast');el.textContent=msg;el.classList.toggle('error',bad);el.classList.add('show');clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
  function confetti(n=20){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const l=$('#confettiLayer');for(let i=0;i<n;i++){const p=document.createElement('i');p.className='confetti-piece';p.style.left=`${Math.random()*100}%`;p.style.animationDelay=`${Math.random()*.3}s`;l.appendChild(p);setTimeout(()=>p.remove(),2300);}}
  function setButtonBusy(btn,on,label){if(!btn)return;if(on){btn.dataset.oldText=btn.textContent;btn.disabled=true;btn.textContent=label||'Working…';}else{btn.disabled=false;btn.textContent=label||btn.dataset.oldText||btn.textContent;}}
  function itemCount(o){return(o.items||[]).reduce((s,i)=>s+Number(i.quantity||0),0);}
  function signed(n){return `${n>0?'+':''}${Number(n)}`;}
  function fmtDate(v,withTime=true){const d=new Date(v);if(Number.isNaN(d.getTime()))return 'Unknown date';return new Intl.DateTimeFormat('en-IE',withTime?{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}:{day:'2-digit',month:'short',year:'numeric'}).format(d);}
  function escapeHTML(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
  function escapeAttr(v=''){return escapeHTML(v).replace(/`/g,'&#96;');}
  function empty(emoji,title,text){return `<div class="empty"><span class="emoji">${emoji}</span><strong>${escapeHTML(title)}</strong><div class="tiny">${escapeHTML(text)}</div></div>`;}
})();
